from typing import Any, Dict, List


class LogQueryRequest:
    def __init__(self, query: str, start_time: str, end_time: str):
        self.query = query
        self.start_time = start_time
        self.end_time = end_time

    def to_dict(self) -> Dict[str, Any]:
        return {
            'query': self.query,
            'startTime': self.start_time,
            'endTime': self.end_time
        }


class LogQueryResponse:
    def __init__(self, logs: List[Dict[str, Any]]):
        self.logs = logs

    @staticmethod
    def from_dict(data: Dict[str, Any]) -> 'LogQueryResponse':
        return LogQueryResponse(logs=data.get('logs', []))


def normalize_log(log: Dict[str, Any]) -> Dict[str, Any]:
    normalized_log = {
        'timestamp': log.get('timestamp'),
        'message': log.get('message'),
        'severity': log.get('severity', 'INFO')
    }
    return normalized_log

import os
import boto3

def get_log_client():
    return boto3.client('logs', region_name=os.getenv('AWS_REGION'))

def create_log_group(log_group_name):
    client = get_log_client()
    client.create_log_group(logGroupName=log_group_name)

def put_log_events(log_group_name, log_stream_name, log_events):
    client = get_log_client()
    client.put_log_events(
        logGroupName=log_group_name,
        logStreamName=log_stream_name,
        logEvents=log_events
    )

import boto3

def write_correlated_logs(log_group_name, log_stream_name, log_events):
    cloudwatch_logs = boto3.client('logs')
    for event in log_events:
        cloudwatch_logs.put_log_events(
            logGroupName=log_group_name,
            logStreamName=log_stream_name,
            logEvents=[{
                'timestamp': int(event['timestamp']),
                'message': event['message']
            }]
        )

